"use client"

import { CheckIcon } from "lucide-react"
import { Badge } from "@/serigraph/ui/badge"
import { Button } from "@/serigraph/ui/button"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/serigraph/ui/card"

// One membership as a plane in its own colour: its name and who it is for, the price in mono for the chosen period,
// the action, and what it includes, each line ticked in ink. The recommended plan carries "Most chosen" by its name
// and its action is the page's one action pill; the others are outline pills. Inside a grid with subgrid rows
// (PLAN_ROWS on the cards' parent), the four parts line up across neighbouring cards whatever their length.

export type Billing = "monthly" | "yearly"

export interface Plan {
  name: string
  audience: string
  /** Kroner a month, paid monthly. */
  monthly: number
  /** Kroner for a year paid at once. */
  yearly: number
  action: string
  features: string[]
  recommended?: boolean
  /** The plane's colour: a tone (1–4), or the colourway's plane when unset. */
  tone?: 1 | 2 | 3 | 4
}

const number = new Intl.NumberFormat("en-GB")

/** A price in kroner: 1,200 kr. */
export const kroner = (n: number) => `${number.format(n)} kr`

/** Classes for the cards' parent at the width where they sit side by side. */
export const PLAN_ROWS = "@min-[54rem]:grid-rows-[auto_auto_auto_1fr]"

/** The price's words for a plan and period. */
function price(plan: Plan, billing: Billing) {
  if (billing === "monthly")
    return {
      price: kroner(plan.monthly),
      per: "a month",
      basis: "Billed monthly. Stop when you like.",
    }
  const saved = plan.monthly * 12 - plan.yearly
  return {
    price: kroner(plan.yearly),
    per: "a year",
    basis:
      saved > 0
        ? `Billed once a year. You save ${kroner(saved)}.`
        : "Billed once a year.",
  }
}

export function PlanCard({
  plan,
  billing,
  onChoose,
}: {
  plan: Plan
  billing: Billing
  onChoose?: (plan: Plan, billing: Billing) => void
}) {
  const { price: figure, per, basis } = price(plan, billing)
  return (
    <Card
      data-tone={plan.tone ? String(plan.tone) : undefined}
      className="@min-[54rem]:row-span-4 @min-[54rem]:grid @min-[54rem]:grid-rows-subgrid"
    >
      <CardHeader className="content-start">
        <CardTitle className="flex flex-wrap items-center gap-x-tight gap-y-hair">
          <h2 className="m-0 font-sans text-h2 leading-h2 font-bold [font-stretch:var(--sans-stretch)]">
            {plan.name}
          </h2>
          {plan.recommended && <Badge>Most chosen</Badge>}
        </CardTitle>
        <CardDescription className="text-body leading-body">
          {plan.audience}
        </CardDescription>
      </CardHeader>
      <CardContent>
        <p className="m-0 flex flex-wrap items-baseline gap-x-tight">
          <span className="font-mono text-title leading-title tabular-nums">
            {figure}
          </span>
          <span className="caps">{per}</span>
        </p>
        <p className="m-0 text-small leading-small">{basis}</p>
      </CardContent>
      <CardContent>
        <Button
          variant={plan.recommended ? "default" : "outline"}
          onClick={() => onChoose?.(plan, billing)}
        >
          {plan.action}
        </Button>
      </CardContent>
      <CardContent>
        <ul
          aria-label={`${plan.name} includes`}
          className="m-0 flex list-none flex-col gap-tight border-t-(length:--line) border-ink p-0 pt-snug"
        >
          {plan.features.map((feature) => (
            <li
              key={feature}
              className="grid grid-cols-[1rem_minmax(0,1fr)] items-start gap-tight text-body leading-ui"
            >
              <CheckIcon
                aria-hidden="true"
                className="mt-0.5 size-4 [stroke-width:calc(var(--line)*1.5)]"
              />
              {feature}
            </li>
          ))}
        </ul>
      </CardContent>
    </Card>
  )
}

"use client"

import { useState } from "react"
import { Folly } from "@/serigraph/extras/folly"
import { Lettering } from "@/serigraph/extras/lettering"
import { cn } from "@/serigraph/lib/utils"
import {
  PLAN_ROWS,
  PlanCard,
  type Billing,
  type Plan,
} from "@/serigraph/blocks/pricing-01-plan"
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/serigraph/ui/accordion"
import { ToggleGroup, ToggleGroupItem } from "@/serigraph/ui/toggle-group"

// Memberships of the observatory: the title lettered beside an arched window, a Monthly/Yearly segmented control
// above three plans on planes of their own colour whose prices follow it, what each includes ticked in ink, and a few
// questions in an accordion at the reading measure. The plans sit side by side when their container is wide enough
// and stack in one readable column when it is not.

export const meta = {
  title: "Pricing",
  description:
    "Three memberships on planes of their own colour, a monthly or yearly price in mono, what each includes ticked, and questions in an accordion.",
}

export const PLANS: Plan[] = [
  {
    name: "Stargazer",
    audience: "For a few clear nights a year.",
    monthly: 60,
    yearly: 600,
    action: "Become a stargazer",
    tone: 3,
    features: [
      "Two dome shows a month",
      "Members’ price on every talk",
      "The sky this month, by email",
    ],
  },
  {
    name: "Observer",
    audience: "For whenever the sky is clear.",
    monthly: 120,
    yearly: 1200,
    action: "Become an observer",
    recommended: true,
    features: [
      "Everything in Stargazer",
      "Every dome show, as often as you like",
      "Two telescope sessions a month",
      "Book four weeks ahead",
      "A guest free on Thursdays",
    ],
  },
  {
    name: "Patron",
    audience: "For friends who keep the dome turning.",
    monthly: 300,
    yearly: 3000,
    action: "Become a patron",
    tone: 4,
    features: [
      "Everything in Observer",
      "The telescopes whenever the deck is open",
      "A seat kept for you at every talk",
      "Your name by the Zeiss refractor",
      "A night on the deck for twelve, once a year",
    ],
  },
]

export const QUESTIONS = [
  {
    q: "What happens when it is cloudy?",
    a: "Telescope sessions move to the next clear night at no cost. Shows and talks go ahead under the dome whatever the weather.",
  },
  {
    q: "Can I bring someone?",
    a: "Observers bring a guest free on Thursdays. Any member can buy guest seats at the members’ price, up to four a night.",
  },
  {
    q: "What happens to sessions I don’t use?",
    a: "Telescope sessions carry over to the next month, then lapse. Dome shows are as often as your membership allows; they don’t carry over.",
  },
  {
    q: "Can I stop at any time?",
    a: "Yes. A monthly membership ends with the month you have paid for; a yearly one is refunded for the whole months left.",
  },
]

export interface Pricing01Props {
  /** Lettered as the page's heading. */
  title?: string
  /** One or two sentences under the title. */
  intro?: string
  plans?: Plan[]
  questions?: { q: string; a: string }[]
  defaultBilling?: Billing
  onChoose?: (plan: Plan, billing: Billing) => void
  className?: string
}

export function Pricing01({
  title = "Join Meridian",
  intro = "Every membership opens the dome, the lecture hall and, on clear nights, the deck. Pay by the month, or by the year and get two months free.",
  plans = PLANS,
  questions = QUESTIONS,
  defaultBilling = "monthly",
  onChoose,
  className,
}: Pricing01Props) {
  const [billing, setBilling] = useState<Billing>(defaultBilling)
  return (
    <div className={cn("@container text-(--text)", className)}>
      <div className="mx-auto max-w-[68rem] px-snug pt-section pb-page @min-[40rem]:px-line">
        <header className="flex items-end justify-between gap-section">
          <div className="min-w-0">
            <p className="m-0 caps">Membership</p>
            <Lettering
              as="h1"
              className="m-0 mt-tight text-[clamp(2.5rem,9cqi,5.5rem)] text-balance"
            >
              {title}
            </Lettering>
            <p className="m-0 mt-snug max-w-measure text-lead leading-lead">
              {intro}
            </p>
          </div>
          <Folly
            template="window"
            seed={`membership:${title}`}
            className="arch-frame hidden w-44 flex-none @min-[48rem]:block"
          />
        </header>

        <div className="mt-section flex flex-wrap items-center gap-x-snug gap-y-hair">
          <ToggleGroup
            aria-label="Billing period"
            spacing={0}
            value={[billing]}
            onValueChange={(next: unknown[]) =>
              next[0] && setBilling(next[0] as Billing)
            }
          >
            <ToggleGroupItem value="monthly">Monthly</ToggleGroupItem>
            <ToggleGroupItem value="yearly">Yearly</ToggleGroupItem>
          </ToggleGroup>
          <span className="caps">Two months free by the year</span>
        </div>

        <div
          className={cn(
            "mt-line grid max-w-[26rem] gap-x-line gap-y-line @min-[54rem]:max-w-none @min-[54rem]:grid-cols-3",
            PLAN_ROWS,
          )}
        >
          {plans.map((plan) => (
            <PlanCard
              key={plan.name}
              plan={plan}
              billing={billing}
              onChoose={onChoose}
            />
          ))}
        </div>

        {questions.length > 0 && (
          <section
            aria-labelledby="pricing-questions"
            className="mt-page max-w-measure"
          >
            <h2
              id="pricing-questions"
              className="m-0 font-sans text-h2 leading-h2 font-bold [font-stretch:var(--sans-stretch)]"
            >
              Questions
            </h2>
            <Accordion className="mt-snug">
              {questions.map(({ q, a }) => (
                <AccordionItem key={q} value={q}>
                  <AccordionTrigger>{q}</AccordionTrigger>
                  <AccordionContent>
                    <p>{a}</p>
                  </AccordionContent>
                </AccordionItem>
              ))}
            </Accordion>
          </section>
        )}
      </div>
    </div>
  )
}

export default Pricing01
